describe("Guzzler: i due casi che falliscono, trasformati in test", async function () {
  const { viem, networkHelpers } = await network.create();
  const publicClient = await viem.getPublicClient();

  async function deployFixture() {
    const created = await viem.deployContract("CreatedWithEvent", [10n]);
    const creator = await viem.deployContract("Creator");
    await creator.write.overrideCreated([created.address]);
    return { created, creator };
  }

  it("n = 100000 non sta in un blocco: la tx finisce il gas", async function () {
    const { creator, created } = await networkHelpers.loadFixture(deployFixture);
    const block = await publicClient.getBlock();
    console.log("block gas limit %d", block.gasLimit);
    // non si passa da revertWith: non c'è un messaggio, il gas è finito
    await assert.rejects(
      creator.write.gasGuzzlerOuter([100000n, 11n]),
      /run out of gas/,
    );
    // nessun effetto sullo stato: x è ancora 10
    assert.equal(await created.read.x(), 10n);
  });

  it("m = 0 fa revert con il messaggio del require", async function () {
    const { creator } = await networkHelpers.loadFixture(deployFixture);
    await viem.assertions.revertWith(
      creator.write.gasGuzzlerOuter([100n, 0n]),
      "Negative parameter causes a revert",
    );
  });

  it("il gas cresce linearmente con n", async function () {
    const used: bigint[] = [];
    for (const n of [0n, 1n, 2n, 10n]) {
      const { creator } = await networkHelpers.loadFixture(deployFixture);
      const hash = await creator.write.gasGuzzlerOuter([n, 11n]);
      const receipt = await publicClient.getTransactionReceipt({ hash });
      used.push(receipt.gasUsed);
      console.log("n = %d -> gasUsed %d", n, receipt.gasUsed);
    }
    console.log("differenza n=1 vs n=0: %d", used[1] - used[0]);
    console.log("differenza n=2 vs n=1: %d", used[2] - used[1]);
    console.log("media per iterazione tra n=2 e n=10: %d", (used[3] - used[2]) / 8n);
  });
});

